VALUES
(
  pg_catalog.gen_random_uuid(),
  'osool-tarahi-site-herfei',
  'اصول طراحی سایت حرفه‌ای؛ ۲۵ نکته برای ساخت سایت سریع و سئوپذیر',
  '۲۵ اصل طراحی سایت سریع، حرفه‌ای و سئوپذیر',
  'راهنمایی عملی برای هماهنگ‌کردن تجربه کاربری، برنامه‌نویسی، سرعت، امنیت و سئو از نخستین تصمیم طراحی تا انتشار و بهبود سایت.',
  'یک سایت حرفه‌ای باید هدف مشخص، مسیر کاربری ساده، محتوای قابل‌فهم، ساختار فنی سالم، سرعت مناسب، امنیت پایه و امکان اندازه‌گیری نتیجه داشته باشد. زیبایی بصری مهم است، اما زمانی ارزش دارد که به پیدا کردن اطلاعات و انجام اقدام اصلی کمک کند.',
  'طراحی وب و سئو',
  'راهنمای جامع',
  ARRAY['اصول طراحی سایت', 'طراحی سایت حرفه‌ای', 'سئو تکنیکال', 'برنامه‌نویسی وب', 'بابلسر', 'مازندران']::text[],
  NULL,
  NULL,
  '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"یک سایت حرفه‌ای فقط مجموعه‌ای از صفحه‌های زیبا نیست. سایت باید به کاربر کمک کند سریع بفهمد کجاست، چه خدمتی دریافت می‌کند و قدم بعدی چیست. در همان زمان باید برای موتور جست‌وجو قابل‌فهم، روی موبایل سریع، از نظر امنیت قابل‌اعتماد و برای توسعه‌های بعدی آماده باشد."}]},{"type":"paragraph","content":[{"type":"text","text":"بخش زیادی از مشکلات سایت‌ها از جایی شروع می‌شود که طراحی، برنامه‌نویسی، محتوا و سئو جدا از هم دیده می‌شوند. طراح روی ظاهر تمرکز می‌کند، برنامه‌نویس بعداً با محدودیت‌های طرح روبه‌رو می‌شود و در آخر از سئوکار انتظار می‌رود همه‌چیز را با چند عنوان و کلمه کلیدی اصلاح کند. نتیجه معمولاً سایتی است که هزینه شده، اما برای کسب‌وکار کار نمی‌کند."}]},{"type":"paragraph","content":[{"type":"text","text":"در این راهنما، مهم‌ترین "},{"type":"text","marks":[{"type":"bold"}],"text":"اصول طراحی سایت"},{"type":"text","text":" را از مرحله برنامه‌ریزی تا انتشار مرور می‌کنیم. هدف این نیست که یک فهرست طولانی از اصطلاحات فنی بسازیم؛ می‌خواهیم ببینیم هر تصمیم چه اثری بر تجربه کاربر، سئو و نتیجه تجاری سایت دارد."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"قبل از طراحی، مسئله را درست تعریف کنید"}]},{"type":"paragraph","content":[{"type":"text","text":"قبل از انتخاب رنگ، فونت یا تکنولوژی باید روشن شود سایت دقیقاً قرار است چه کاری انجام دهد. اگر پاسخ فقط «معرفی کسب‌وکار» باشد، هنوز مسئله به‌اندازه کافی دقیق تعریف نشده است. معرفی برای چه مخاطبی و با چه نتیجه‌ای؟ تماس تلفنی، تکمیل فرم مشاوره، خرید، رزرو یا مشاهده نمونه‌کار؟"}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"۱. برای هر صفحه یک هدف اصلی تعیین کنید"}]},{"type":"paragraph","content":[{"type":"text","text":"صفحه اصلی نمی‌تواند هم‌زمان ده اقدام را با اهمیت یکسان از کاربر بخواهد. یک اقدام اصلی انتخاب کنید و بقیه را در سطح دوم قرار دهید. برای نمونه، در سایت یک توسعه‌دهنده ممکن است اقدام اصلی «درخواست مشاوره» و اقدام دوم «مشاهده نمونه‌کارها» باشد."}]},{"type":"paragraph","content":[{"type":"text","text":"وقتی هدف صفحه روشن باشد، تصمیم‌گیری درباره تیتر، ترتیب بخش‌ها، متن دکمه‌ها و حتی اطلاعات فرم ساده‌تر می‌شود. هر بخشی که به این هدف کمک نمی‌کند باید حذف، کوتاه یا به صفحه دیگری منتقل شود."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"۲. مخاطب را با یک عنوان کلی تعریف نکنید"}]},{"type":"paragraph","content":[{"type":"text","text":"عبارت‌هایی مثل «همه کسب‌وکارها» یا «تمام کاربران اینترنت» برای طراحی کاربردی نیستند. لازم است بدانید کاربر اصلی چه نیازی دارد، با چه سطحی از دانش وارد سایت می‌شود و پیش از تماس چه تردیدهایی دارد."}]},{"type":"paragraph","content":[{"type":"text","text":"برای یک سایت خدمات طراحی وب، مشتری معمولاً می‌خواهد این موارد را سریع پیدا کند: نوع خدمات، نمونه پروژه‌های واقعی، روش همکاری، بازه تقریبی زمان اجرا، پاسخ به نگرانی‌های فنی و یک راه تماس ساده. ساختار سایت باید پاسخ همین پرسش‌ها را جلوتر از توضیحات طولانی درباره خود برند قرار دهد."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"۳. محتوا را پیش از طراحی جدی بگیرید"}]},{"type":"paragraph","content":[{"type":"text","text":"طراحی با متن‌های آزمایشی اغلب در مرحله اجرا به مشکل می‌خورد. تیتر واقعی ممکن است دو خط شود، جدول خدمات فضای بیشتری بخواهد یا یک نمونه‌کار به توضیح کامل‌تری نیاز داشته باشد. بهتر است پیش از طراحی نهایی، دست‌کم اسکلت محتوای هر صفحه آماده باشد."}]},{"type":"paragraph","content":[{"type":"text","text":"این کار فقط به ظاهر صفحه کمک نمی‌کند. معماری اطلاعات، لینک‌سازی داخلی و حتی انتخاب URLها نیز به محتوای واقعی وابسته‌اند."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"۴. شاخص موفقیت را از ابتدا مشخص کنید"}]},{"type":"paragraph","content":[{"type":"text","text":"«بازدید بیشتر» شاخص کاملی نیست. ممکن است ترافیک بالا برود، اما هیچ درخواست مناسبی ثبت نشود. برای یک سایت خدماتی می‌توان تعداد فرم‌های معتبر، تماس‌های ورودی، مشاهده نمونه‌کار و نرخ تبدیل صفحه خدمات را اندازه گرفت."}]},{"type":"paragraph","content":[{"type":"text","text":"بدون شاخص مشخص، بعد از انتشار نمی‌توان فهمید کدام تغییر مفید بوده و کدام فقط ظاهر سایت را عوض کرده است."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"اصول تجربه کاربری و طراحی رابط"}]},{"type":"paragraph","content":[{"type":"text","text":"تجربه کاربری خوب معمولاً به چشم نمی‌آید؛ کاربر بدون مکث مسیرش را پیدا می‌کند. در مقابل، یک دکمه نامشخص، منوی شلوغ یا فرم طولانی می‌تواند کاربر آماده خرید را از سایت خارج کند."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"۵. طراحی را از موبایل شروع کنید"}]},{"type":"paragraph","content":[{"type":"text","text":"فضای محدود موبایل شما را مجبور می‌کند مهم‌ترین محتوا را زودتر مشخص کنید. در نسخه موبایل، عنوان صفحه، توضیح کوتاه، اقدام اصلی و نشانه‌های اعتماد باید بدون اسکرول‌های غیرضروری در دسترس باشند."}]},{"type":"paragraph","content":[{"type":"text","text":"موبایل‌فرست بودن فقط کوچک کردن اجزای دسکتاپ نیست. منو، جدول‌ها، فرم‌ها، فاصله لمس دکمه‌ها و ترتیب نمایش بخش‌ها باید جداگانه برای صفحه کوچک تصمیم‌گیری شوند. گوگل نیز برای ایندکس و رتبه‌بندی از نسخه موبایل محتوا استفاده می‌کند؛ بنابراین حذف محتوای اصلی از نسخه موبایل تصمیم مناسبی نیست."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"۶. سلسله‌مراتب بصری روشنی بسازید"}]},{"type":"paragraph","content":[{"type":"text","text":"کاربر باید با یک نگاه تفاوت عنوان اصلی، زیرعنوان، متن عادی و اقدام مهم را تشخیص دهد. اگر همه تیترها بزرگ، همه دکمه‌ها رنگی و چند بخش هم‌زمان متحرک باشند، هیچ عنصر واقعاً مهمی باقی نمی‌ماند."}]},{"type":"paragraph","content":[{"type":"text","text":"برای ایجاد سلسله‌مراتب، فقط به اندازه فونت تکیه نکنید. فضای خالی، رنگ، ضخامت نوشته، محل قرارگیری و ترتیب محتوا در کنار هم توجه کاربر را هدایت می‌کنند."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"۷. منو را براساس نیاز کاربر بچینید"}]},{"type":"paragraph","content":[{"type":"text","text":"نام آیتم‌های منو باید واضح باشد: «خدمات»، «نمونه‌کارها»، «مقالات»، «درباره من» و «تماس» از عبارت‌های خلاقانه اما مبهم بهترند. کاربر نباید برای فهمیدن مقصد یک لینک حدس بزند."}]},{"type":"paragraph","content":[{"type":"text","text":"در سایت‌های کوچک، افزودن منوهای چندسطحی معمولاً ضروری نیست. هر صفحه مهم باید حداکثر با چند کلیک از صفحه اصلی قابل دسترسی باشد و مسیر برگشت روشنی داشته باشد."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"۸. فرم را به‌اندازه اطلاعات موردنیاز کوتاه کنید"}]},{"type":"paragraph","content":[{"type":"text","text":"هر فیلد اضافه احتمال نیمه‌کاره ماندن فرم را بیشتر می‌کند. اگر برای تماس اولیه فقط نام، شماره تماس و توضیح کوتاه پروژه لازم است، پرسیدن بودجه دقیق، آدرس کامل و چند انتخاب دیگر را می‌توان به گفت‌وگوی بعدی منتقل کرد."}]},{"type":"paragraph","content":[{"type":"text","text":"پیام خطا هم باید دقیق باشد. «اطلاعات نامعتبر است» به کاربر کمکی نمی‌کند؛ اما «شماره موبایل را با ۱۱ رقم وارد کنید» مشکل را روشن می‌گوید. بعد از ارسال نیز نمایش پیام موفقیت و کد پیگیری، اطمینان کاربر را بیشتر می‌کند."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"۹. دسترس‌پذیری را بخشی از طراحی بدانید"}]},{"type":"paragraph","content":[{"type":"text","text":"کنتراست مناسب، فوکوس قابل‌مشاهده برای کاربر کیبورد، برچسب واقعی برای فیلدهای فرم، ترتیب منطقی تیترها و متن جایگزین تصاویر از اصول پایه‌اند. این موارد سایت را برای افراد بیشتری قابل‌استفاده می‌کنند و معمولاً کیفیت ساختار صفحه را هم بالا می‌برند."}]},{"type":"paragraph","content":[{"type":"text","text":"برای بررسی دقیق‌تر می‌توان از استاندارد "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://www.w3.org/TR/WCAG22/","target":"_blank","rel":"noopener noreferrer nofollow","class":null,"title":null}}],"text":"WCAG 2.2"},{"type":"text","text":" و ابزارهای تست خودکار استفاده کرد، اما تست خودکار جای کار با کیبورد و بررسی واقعی صفحه را نمی‌گیرد."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"۱۰. حرکت و انیمیشن باید دلیل داشته باشد"}]},{"type":"paragraph","content":[{"type":"text","text":"انیمیشن می‌تواند تغییر وضعیت، باز شدن یک بخش یا موفقیت یک عملیات را روشن کند. در مقابل، حرکت دائمی پس‌زمینه، ورود هم‌زمان چندین عنصر و افکت‌هایی که خواندن را عقب می‌اندازند، بیشتر مزاحمت ایجاد می‌کنند."}]},{"type":"paragraph","content":[{"type":"text","text":"برای کاربرانی که گزینه کاهش حرکت را در سیستم‌عامل فعال کرده‌اند، حالت "},{"type":"text","marks":[{"type":"code"}],"text":"prefers-reduced-motion"},{"type":"text","text":" را در نظر بگیرید. همچنین هیچ اطلاعات ضروری نباید فقط با انیمیشن قابل‌فهم باشد."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"اصول برنامه‌نویسی و زیرساخت فنی"}]},{"type":"paragraph","content":[{"type":"text","text":"کاربر کد سایت را نمی‌بیند، اما نتیجه آن را حس می‌کند: سرعت باز شدن صفحه، ثبات فرم، امنیت اطلاعات و این‌که سایت با هر تغییر کوچک از کار نیفتد."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"۱۱. تکنولوژی را براساس مسئله انتخاب کنید"}]},{"type":"paragraph","content":[{"type":"text","text":"هیچ فریم‌ورک یا سیستم مدیریت محتوایی برای همه پروژه‌ها بهترین نیست. یک سایت شرکتی با چند صفحه ثابت، فروشگاه دارای هزاران محصول و وب‌اپلیکیشن دارای پنل کاربری نیازهای متفاوتی دارند."}]},{"type":"paragraph","content":[{"type":"text","text":"انتخاب تکنولوژی باید با توجه به نوع محتوا، تعداد ویرایش‌کنندگان، قابلیت‌های موردنیاز، بودجه نگهداری، تجربه تیم و برنامه توسعه آینده انجام شود. استفاده از ابزار پیچیده برای مسئله ساده، هزینه ساخت و پشتیبانی را بی‌دلیل بالا می‌برد."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"۱۲. HTML معنایی بنویسید"}]},{"type":"paragraph","content":[{"type":"text","text":"عناصری مثل "},{"type":"text","marks":[{"type":"code"}],"text":"header"},{"type":"text","text":"، "},{"type":"text","marks":[{"type":"code"}],"text":"nav"},{"type":"text","text":"، "},{"type":"text","marks":[{"type":"code"}],"text":"main"},{"type":"text","text":"، "},{"type":"text","marks":[{"type":"code"}],"text":"article"},{"type":"text","text":" و "},{"type":"text","marks":[{"type":"code"}],"text":"footer"},{"type":"text","text":" فقط جایگزین ظاهری "},{"type":"text","marks":[{"type":"code"}],"text":"div"},{"type":"text","text":" نیستند. آن‌ها نقش بخش‌های صفحه را برای مرورگر، صفحه‌خوان و موتور جست‌وجو روشن می‌کنند."}]},{"type":"paragraph","content":[{"type":"text","text":"دکمه باید واقعاً "},{"type":"text","marks":[{"type":"code"}],"text":"button"},{"type":"text","text":" باشد و لینک برای رفتن به یک آدرس استفاده شود. شبیه‌سازی این رفتارها با عناصر نامرتبط، استفاده با کیبورد و ابزارهای کمکی را دشوار می‌کند."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"۱۳. رندر محتوا را قابل‌اعتماد نگه دارید"}]},{"type":"paragraph","content":[{"type":"text","text":"گوگل امکان پردازش جاوااسکریپت را دارد، اما این به آن معنا نیست که هر پیاده‌سازی سمت کاربر بدون مشکل است. محتوای اصلی، عنوان و لینک‌های مهم بهتر است در پاسخ اولیه یا از طریق رندر سمت سرور و تولید استاتیک در دسترس باشند."}]},{"type":"paragraph","content":[{"type":"text","text":"در پروژه‌هایی که از React یا Next.js استفاده می‌کنند، لازم نیست همه صفحه‌ها با یک روش رندر شوند. صفحه مقاله می‌تواند استاتیک و سریع باشد، در حالی که داشبورد کاربر به داده پویا نیاز دارد. انتخاب باید صفحه‌به‌صفحه و براساس نیاز انجام شود."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"۱۴. جاوااسکریپت ارسالی به مرورگر را محدود کنید"}]},{"type":"paragraph","content":[{"type":"text","text":"هر کتابخانه‌ای که نصب می‌شود بخشی از هزینه خود را به کاربر منتقل می‌کند. تقسیم کد، بارگذاری تنبل بخش‌های غیراصلی، حذف وابستگی‌های بلااستفاده و اجرای منطق تا حد امکان روی سرور می‌تواند حجم جاوااسکریپت مرورگر را کاهش دهد."}]},{"type":"paragraph","content":[{"type":"text","text":"نکته مهم این است که بهینه‌سازی با اندازه‌گیری شروع شود. حذف چند کیلوبایت از یک فایل کم‌اهمیت، در حالی که تصویر اصلی صفحه چند مگابایت حجم دارد، اولویت درستی نیست."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"۱۵. تصویر و فونت را جزئی از عملکرد بدانید"}]},{"type":"paragraph","content":[{"type":"text","text":"ابعاد تصویر باید متناسب با محل نمایش باشد. فرستادن تصویر ۴۰۰۰ پیکسلی برای کارتی با عرض ۴۰۰ پیکسل، پهنای باند را هدر می‌دهد. استفاده از "},{"type":"text","marks":[{"type":"code"}],"text":"srcset"},{"type":"text","text":" یا ابزار بهینه‌سازی تصویر فریم‌ورک، فرمت‌های WebP و AVIF، بارگذاری تنبل تصاویر پایین صفحه و تعیین عرض و ارتفاع، معمولاً اثر محسوسی دارد."}]},{"type":"paragraph","content":[{"type":"text","text":"فونت فارسی هم می‌تواند سنگین باشد. وزن‌های غیرضروری را حذف کنید، فایل‌ها را بهینه و در صورت امکان نسخه موردنیاز را میزبانی کنید تا اتصال به سرویس‌های متعدد سرعت صفحه را کاهش ندهد."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"۱۶. امنیت را به بعد از انتشار موکول نکنید"}]},{"type":"paragraph","content":[{"type":"text","text":"فعال بودن HTTPS فقط نقطه شروع است. ورودی‌های کاربر باید در سمت سرور اعتبارسنجی شوند، دسترسی به عملیات مدیریتی در خود سرور کنترل شود و کلیدهای خصوصی هرگز وارد کد سمت مرورگر یا مخزن عمومی نشوند."}]},{"type":"paragraph","content":[{"type":"text","text":"برای فرم‌ها و پنل مدیریت نیز محدودسازی درخواست، محافظت در برابر ارسال خودکار، ثبت رخدادهای مهم و به‌روزرسانی وابستگی‌ها لازم است. "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://owasp.org/www-project-top-ten/","target":"_blank","rel":"noopener noreferrer nofollow","class":null,"title":null}}],"text":"OWASP Top 10"},{"type":"text","text":" مرجع مناسبی برای شناخت ریسک‌های رایج برنامه‌های وب است."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"۱۷. کد قابل‌نگهداری تحویل دهید"}]},{"type":"paragraph","content":[{"type":"text","text":"سایتی که امروز منتشر می‌شود، فردا به ویرایش محتوا، اصلاح خطا و قابلیت جدید نیاز دارد. نام‌گذاری روشن، تفکیک منطق، مدیریت خطای یکپارچه، migration برای دیتابیس و مستند کردن تنظیمات ضروری، هزینه تغییرات بعدی را پایین می‌آورد."}]},{"type":"paragraph","content":[{"type":"text","text":"تست هم باید متناسب با ریسک باشد. مسیرهای مهم مثل ورود، ثبت فرم، پرداخت یا انتشار مقاله ارزش تست خودکار بیشتری از یک انیمیشن تزئینی دارند."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"اصول سئو در طراحی سایت"}]},{"type":"paragraph","content":[{"type":"text","text":"سئو از زمان طراحی معماری سایت شروع می‌شود، نه بعد از تمام شدن پروژه. اگر صفحه‌ها هدف مشخص نداشته باشند، محتوای اصلی فقط پس از تعامل کاربر بارگذاری شود یا لینک‌های داخلی ناقص باشند، نصب یک افزونه سئو مشکل را حل نمی‌کند."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"۱۸. برای هر صفحه یک نیت جست‌وجوی مشخص داشته باشید"}]},{"type":"paragraph","content":[{"type":"text","text":"کاربری که «اصول طراحی سایت» را جست‌وجو می‌کند، به‌دنبال آموزش و چک‌لیست است. کسی که «سفارش طراحی سایت در بابلسر» را می‌نویسد، احتمالاً می‌خواهد خدمات، نمونه‌کار، هزینه و راه تماس را ببیند. این دو نیاز نباید در یک صفحه با هم رقابت کنند."}]},{"type":"paragraph","content":[{"type":"text","text":"برای هر URL یک موضوع و هدف اصلی تعیین کنید. صفحه خدمات می‌تواند به مقاله آموزشی لینک بدهد و مقاله نیز در زمان مناسب کاربر را به صفحه خدمات یا فرم مشاوره هدایت کند."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"۱۹. عنوان و توضیحات را برای تصمیم کاربر بنویسید"}]},{"type":"paragraph","content":[{"type":"text","text":"عنوان صفحه باید یکتا، روشن و متناسب با محتوای واقعی باشد. قرار دادن عبارت اصلی در عنوان مفید است، اما تکرار چندین کلمه مشابه، عنوان را بهتر نمی‌کند. توضیحات متا نیز خلاصه‌ای دقیق و ترغیب‌کننده بنویسد؛ گوگل ممکن است بسته به جست‌وجوی کاربر بخش دیگری از متن صفحه را نمایش دهد."}]},{"type":"paragraph","content":[{"type":"text","text":"در خود محتوا فقط یک H1 واضح داشته باشید و زیرعنوان‌ها را براساس رابطه بخش‌ها انتخاب کنید، نه صرفاً برای بزرگ‌تر شدن نوشته."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"۲۰. کلمه کلیدی را طبیعی و در بافت درست استفاده کنید"}]},{"type":"paragraph","content":[{"type":"text","text":"درصد ثابتی برای «تراکم کلمه کلیدی» وجود ندارد. عبارت اصلی باید در عنوان، مقدمه و بخش‌های مرتبط حضور طبیعی داشته باشد و واژه‌های هم‌معنا نیز به فهم بهتر موضوع کمک کنند. اگر جمله‌ای فقط برای تکرار عبارت هدف نوشته شده، معمولاً بهتر است حذف شود."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"link","attrs":{"href":"https://developers.google.com/search/docs/fundamentals/creating-helpful-content","target":"_blank","rel":"noopener noreferrer nofollow","class":null,"title":null}}],"text":"راهنمای محتوای مفید گوگل"},{"type":"text","text":" تأکید می‌کند که محتوا باید در درجه اول برای مخاطب واقعی نوشته شود و پس از مطالعه، نیاز او را برطرف کند؛ نه این‌که فقط خلاصه‌ای از مطالب دیگر سایت‌ها باشد."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"۲۱. لینک‌سازی داخلی را براساس ارتباط انجام دهید"}]},{"type":"paragraph","content":[{"type":"text","text":"لینک داخلی به گوگل در پیدا کردن صفحه‌ها و فهم ارتباط آن‌ها کمک می‌کند و مسیر مطالعه کاربر را هم ادامه می‌دهد. متن لینک باید مقصد را توضیح دهد؛ «مشاهده نمونه‌کارهای طراحی سایت» بهتر از «اینجا کلیک کنید» است."}]},{"type":"paragraph","content":[{"type":"text","text":"عدد ثابتی برای تعداد لینک داخلی وجود ندارد. هرجا یک صفحه واقعاً پاسخ مرحله بعدی کاربر را می‌دهد، لینک آن مفید است. لینک‌های ساخته‌نشده یا حذف‌شده نیز نباید به خطای ۴۰۴ ختم شوند."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"۲۲. خزش و ایندکس را کنترل کنید"}]},{"type":"paragraph","content":[{"type":"text","text":"صفحه مهم باید از طریق لینک معمولی HTML قابل دسترسی باشد، پاسخ موفق "},{"type":"text","marks":[{"type":"code"}],"text":"200"},{"type":"text","text":" بدهد و ناخواسته "},{"type":"text","marks":[{"type":"code"}],"text":"noindex"},{"type":"text","text":" نشده باشد. "},{"type":"text","marks":[{"type":"code"}],"text":"robots.txt"},{"type":"text","text":" برای مدیریت خزش است و ابزار مناسبی برای خصوصی نگه داشتن صفحه‌های حساس نیست."}]},{"type":"paragraph","content":[{"type":"text","text":"نقشه سایت به کشف URLها کمک می‌کند، به‌ویژه وقتی سایت تازه است یا لینک خارجی کمی دارد. آن را در Search Console ثبت کنید یا مسیرش را در "},{"type":"text","marks":[{"type":"code"}],"text":"robots.txt"},{"type":"text","text":" بنویسید. قرار دادن لینک نقشه سایت در فوتر الزام سئو نیست. همچنین ارسال sitemap تضمین ایندکس یا رتبه نیست؛ فقط یک راهنما برای موتور جست‌وجو است."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"۲۳. داده ساختاریافته را دقیق و محدود پیاده‌سازی کنید"}]},{"type":"paragraph","content":[{"type":"text","text":"Schema زمانی مفید است که اطلاعات واقعی صفحه را توصیف کند. برای مقاله می‌توان از "},{"type":"text","marks":[{"type":"code"}],"text":"BlogPosting"},{"type":"text","text":" همراه با عنوان، تصویر، نویسنده، "},{"type":"text","marks":[{"type":"code"}],"text":"datePublished"},{"type":"text","text":" و "},{"type":"text","marks":[{"type":"code"}],"text":"dateModified"},{"type":"text","text":" واقعی استفاده کرد. "},{"type":"text","marks":[{"type":"code"}],"text":"BreadcrumbList"},{"type":"text","text":" نیز موقعیت صفحه در ساختار سایت را نشان می‌دهد."}]},{"type":"paragraph","content":[{"type":"text","text":"اضافه کردن چند نوع Schema نامرتبط، شانس رتبه را بیشتر نمی‌کند. داده‌ها باید با چیزی که کاربر روی صفحه می‌بیند یکسان باشند و پیش از انتشار با ابزار Rich Results Test بررسی شوند."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"۲۴. Core Web Vitals را با داده واقعی بسنجید"}]},{"type":"paragraph","content":[{"type":"text","text":"سه معیار اصلی تجربه صفحه عبارت‌اند از:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"LCP:"},{"type":"text","text":" نمایش بزرگ‌ترین محتوای اصلی؛ مقدار خوب حداکثر ۲٫۵ ثانیه است."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"INP:"},{"type":"text","text":" سرعت پاسخ صفحه به تعامل؛ مقدار خوب حداکثر ۲۰۰ میلی‌ثانیه است."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"CLS:"},{"type":"text","text":" ثبات چیدمان هنگام بارگذاری؛ مقدار خوب حداکثر ۰٫۱ است."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"این آستانه‌ها باید برای دست‌کم ۷۵ درصد بازدیدها مناسب باشند. گزارش Chrome UX و Search Console داده کاربران واقعی را نشان می‌دهد؛ Lighthouse بیشتر برای آزمایش و پیدا کردن مشکل در محیط کنترل‌شده مناسب است."}]},{"type":"paragraph","content":[{"type":"text","text":"بهبود Core Web Vitals برای کاربر و سئو ارزشمند است، اما به‌تنهایی رتبه بالا را تضمین نمی‌کند. کیفیت محتوا، ارتباط با جست‌وجو، اعتبار و امکان خزش همچنان تعیین‌کننده‌اند. جزئیات معیارها در "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://developers.google.com/search/docs/appearance/core-web-vitals","target":"_blank","rel":"noopener noreferrer nofollow","class":null,"title":null}}],"text":"مستندات رسمی Core Web Vitals"},{"type":"text","text":" آمده است."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"۲۵. بعد از انتشار، اندازه‌گیری و اصلاح کنید"}]},{"type":"paragraph","content":[{"type":"text","text":"انتشار پایان کار نیست. Search Console نشان می‌دهد کاربران با چه عبارت‌هایی صفحه را دیده‌اند، کدام URLها ایندکس شده‌اند و آیا مشکل فنی وجود دارد. ابزار تحلیل رفتار نیز می‌تواند مسیر ورود، کلیک روی اقدام اصلی و تکمیل فرم را روشن کند."}]},{"type":"paragraph","content":[{"type":"text","text":"هر تغییر باید براساس داده و با هدف مشخص انجام شود. تغییر مداوم عنوان یا تاریخ بدون بهبود واقعی محتوا، نشانه به‌روزرسانی مفید نیست."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"وردپرس یا طراحی اختصاصی؟"}]},{"type":"paragraph","content":[{"type":"text","text":"انتخاب بین وردپرس و برنامه‌نویسی اختصاصی، انتخاب بین «خوب» و «بد» نیست. سؤال درست این است که کدام راه با نیاز، بودجه و برنامه آینده پروژه هماهنگ‌تر است."}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"معیار"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"